import{_ as d,a0 as i,w as a,s,ao as l,I as p,a1 as n,A as r,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"安卓編年史（25）：Android 4.4，奇巧——更完美，更少的內存佔用（2） | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（25）：Android 4.4，奇巧——更完美，更少的內存佔用（2） | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（25）：Android 4.4，奇巧——更完美，更少的內存佔用（2） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（25）：Android 4.4，奇巧——更完美，更少的內存佔用（2） | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/26 - The history of Android","title":"安卓編年史（25）：Android 4.4，奇巧——更完美，更少的內存佔用（2）","tag":"The history of Android","desc":""},"relativePath":"The history of Android/26 - The history of Android.md","filePath":"[post].md"}'),m={name:"The history of Android/26 - The history of Android.md"};function g(h,o,f,u,T,A){const e=i("Link");return a(),s("div",null,[o[14]||(o[14]=l('<h1 id="安卓編年史-25-android-4-4-奇巧——更完美-更少的內存佔用-2" tabindex="-1">安卓編年史（25）：Android 4.4，奇巧——更完美，更少的內存佔用（2） <a class="header-anchor" href="#安卓編年史-25-android-4-4-奇巧——更完美-更少的內存佔用-2" aria-label="Permalink to “安卓編年史（25）：Android 4.4，奇巧——更完美，更少的內存佔用（2）”">​</a></h1><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/homesetupthrowback.png" alt="新的“添加到主屏幕”界面無疑受到了蜂巢的啓發。"></p><p><em>新的“添加到主屏幕”界面無疑受到了蜂巢的啓發。 [Ron Amadeo 供圖]</em></p><p>奇巧的主屏幕配置界面漂亮地對蜂巢進行了復古。在有巨大的 10 英寸屏幕的蜂巢平板上（上方右側圖片），長按主屏背景會向你展現一個所有主屏幕的縮放視圖。可以從下面的小部件抽屜裏將它們拖放到任意主屏上——這很方便。在將蜂巢的界面帶到手機上時，從安卓 4.0 直到 4.3，谷歌都跳過了這個設計，把它留給了大屏幕設備，在手機上長按後只顯示一個選項列表（中間的圖片）。</p><p>但在奇巧上，谷歌最終給出瞭解決方案。在長按後，4.4 呈現一個略微縮放的視圖——你可以看到當前主屏以及它左右側的屏幕。點擊“小部件”按鈕會打開一個小部件略縮圖的完整列表，但是長按一個小部件後，你會回到縮放視圖，並且你可以在主屏頁面之間滾動，將圖標放在你想要的位置。將圖標或者小部件拖動過最右側的主屏頁面，你可以創建一個新的主屏頁面。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/RIP33B5E5.png" alt="聯繫人和去掉所有藍色痕跡的鍵盤。"></p><p><em>聯繫人和去掉所有藍色痕跡的鍵盤。 [Ron Amadeo 供圖]</em></p><p>奇巧是電子風格設計的完結。在系統的大多數地方，剩下的藍色高亮都被換成了灰色。在聯繫人應用中，頭部和聯繫人列表字母分割線的藍色都移除掉了。圖片的位置換了一側，底欄變成了淺灰色以和頂部相稱。幾乎將藍色滲透進每個應用的鍵盤，現在是灰底、灰色、灰高亮。這可不是件壞事。應用應該允許有它們自己的配色方案——在鍵盤上強迫存在潛在的顏色衝突可不是個好設計。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/phone.png" alt="前三張是奇巧的撥號盤，最後一張是 4.3 的。"></p><p><em>前三張是奇巧的撥號盤，最後一張是 4.3 的。 [Ron Amadeo 供圖]</em></p><p>谷歌完全重製了奇巧中的撥號，創造了一個瘋狂的設計，改變了用户對手機的思考方式。實際上新版撥號中的數字都被儘可能地隱藏了——在首屏上甚至沒有撥號盤。打電話的主要界面現在是個搜索欄！如果你想給你的聯繫人打電話，只要在搜索欄輸入他的名字；如果你想給一個公司打電話，只要輸入公司的名字，撥號會通過谷歌地圖龐大的資料庫找到號碼。它工作得令人難以置信的好，這是隻有谷歌才能完成的事情。</p><p>如果搜索不是你的菜的話，應用還會智能地顯示通話記錄列表，最常聯繫人，還有指向所有聯繫人的鏈接。底部的鏈接指向你的通話記錄，傳統的撥號盤，以及常規的更多操作按鈕，包含一個設置頁面。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/googledrive-and-printing.png" alt="Office 相關：新的內置應用 Google Drive，以及打印支持。"></p><p><em>Office 相關：新的內置應用 Google Drive，以及打印支持。 [Ron Amadeo 供圖]</em></p><p>在奇巧中 Google Drive 終於作為內置應用包含了進來，令人驚奇的是這居然等了這麼長時間。Drive 允許用户創建和編輯 Google Docs 表格和文檔，用相機掃描文檔並作為 PDF 上傳，或者查看（不能編輯）演示文稿。Drive 的設計十分現代，側面擁有滑出式導航抽屜，並且是 Google Now 風格卡片式設計。</p><p>為了有更多的移動辦公樂趣，奇巧包含了系統級打印框架。在設置的底部有“打印”設置界面，任何打印機 OEM 廠商都可以為它寫個插件。谷歌雲打印自然是首批支持者之一。只要你的打印機和雲打印相連接，無論是本地或通過一台裝有 Chrome 瀏覽器的電腦，你都可以藉助網絡進行打印。應用同樣也需要支持打印框架。點擊 Google Drive 裏的“i”按鈕會顯示文檔信息，並且給你打印的選項。就像桌面系統那樣，會彈出一個設置對話框，有打印份數，紙張尺寸，以及頁面選擇等選項。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/that-is-one-dead-gallery.png" alt="Google+ 應用的“相片”部分，它取代了相冊。"></p><p><em>Google+ 應用的“相片”部分，它取代了相冊。 [Ron Amadeo 供圖]</em></p><p>Google+ 相片和相冊最初都在 Nexus 5 上隨附，但在 Google Play 設備稍晚版本的奇巧上，相冊被砍掉了，Google+ 完全接手了相片管理。新應用的主題從深色變成了淺色，Google+ 相片還帶來了現代的導航抽屜設計。</p><p>安卓一直以來都有即時上傳功能，它會自動備份所有圖片到谷歌的雲存儲，開始是 Picasa 後來是 Google+。G+ 相片相比相冊最大的好處是它可以管理那些雲端存儲的圖片。圖片右下角的雲圖標指示備份狀態，它會從右到左地填滿來指示上傳狀態。G+ 相片帶來了它自己的照片編輯器，還有許多其它的 Google+ 圖片功能，比如高亮，自動美化，當然，還有分享到 Google+。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/clocks.png" alt="時鐘應用的調整，添加了一個鬧鐘頁面並修改了時間輸入框。"></p><p><em>時鐘應用的調整，添加了一個鬧鐘頁面並修改了時間輸入框。 [Ron Amadeo 供圖]</em></p><p>谷歌將 4.2 引入的優秀時間選擇器換成了一個奇怪的時鐘界面，操作起來比舊界面更慢了也更不精確了。首先是個可以選擇小時的單指針時鐘，然後顯示的是另一個選擇分鐘的單指針時鐘。選擇的時候要轉動分針或點擊數字，這讓用用户很難選擇不是整五分鐘的時間增量。不像之前的時間選擇器需要選擇一個時間段，這裏默認時間段是 AM（重複一下，這樣設置的時候容易不小心偏差 12 小時）。</p><hr><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/05/r.amadeo-45843.jpg" alt="Ron Amadeo"></p>',25)),p("p",null,[n(e,{href:"http://arstechnica.com/author/ronamadeo"},{default:r(()=>[...o[0]||(o[0]=[t("Ron Amadeo",-1)])]),_:1}),o[2]||(o[2]=t(" / Ron 是 Ars Technica 的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。",-1)),n(e,{href:"https://twitter.com/RonAmadeo"},{default:r(()=>[...o[1]||(o[1]=[t("@RonAmadeo",-1)])]),_:1})]),o[15]||(o[15]=p("hr",null,null,-1)),p("p",null,[o[4]||(o[4]=t("via: ",-1)),n(e,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/26/"},{default:r(()=>[...o[3]||(o[3]=[t("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/26/",-1)])]),_:1})]),p("p",null,[o[7]||(o[7]=t("譯者：",-1)),n(e,{href:"https://github.com/alim0x"},{default:r(()=>[...o[5]||(o[5]=[t("alim0x",-1)])]),_:1}),o[8]||(o[8]=t(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:r(()=>[...o[6]||(o[6]=[t("wxy",-1)])]),_:1})]),p("p",null,[o[11]||(o[11]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...o[9]||(o[9]=[t("LCTT",-1)])]),_:1}),o[12]||(o[12]=t(" 原創翻譯，",-1)),n(e,{href:"http://linux.cn/"},{default:r(()=>[...o[10]||(o[10]=[t("Linux中國",-1)])]),_:1}),o[13]||(o[13]=t(" 榮譽推出",-1))])])}const G=d(m,[["render",g]]);export{C as __pageData,G as default};
